// The synthetic demo dataset (SPEC § 12). Not market data.

import { type Calendar, defaultCalendar } from './calendar';
import type { Bars } from './data';
import { MS_MINUTE, isoWithOffset, parseDate } from './time';

export interface DemoOptions {
  seed?: number;
  from?: string;
  to?: string;
  calendar?: Calendar;
}

export const DEMO_FROM = '2023-01-03';
export const DEMO_TO = '2024-12-31';

/** Mulberry32 (SPEC § 12.1). `next()` returns the draw u in [0, 1); `nextRaw()` the 32-bit r. */
export class Mulberry32 {
  private a: number;
  constructor(seed: number) {
    this.a = seed >>> 0;
  }
  nextRaw(): number {
    this.a = (this.a + 0x6d2b79f5) >>> 0;
    let t = this.a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t = (t ^ ((t + Math.imul(t ^ (t >>> 7), t | 61)) >>> 0)) >>> 0;
    return (t ^ (t >>> 14)) >>> 0;
  }
  next(): number {
    return this.nextRaw() / 4294967296;
  }
  /** Irwin-Hall: the sum of twelve draws, left to right, minus 6. */
  normal(): number {
    let s = 0;
    for (let i = 0; i < 12; i++) s += this.next();
    return s - 6;
  }
}

function profile(m: number): number {
  if (m < 960) return 1.8;
  if (m < 1050) return 1.2;
  if (m < 1200) return 0.8;
  if (m < 1260) return 1.0;
  return 1.4;
}

const R = (x: number): number => (x >= 0 ? Math.floor(x + 0.5) : -Math.floor(-x + 0.5));

/** The demo bars for a seed and a date range (only trading days are generated). */
export function demoBars(options: DemoOptions = {}): Bars {
  const cal = options.calendar ?? defaultCalendar();
  const seed = options.seed ?? 1;
  const from = parseDate(options.from ?? DEMO_FROM);
  const to = parseDate(options.to ?? DEMO_TO);
  if (from === null || to === null) throw new RangeError('demoBars: from and to must be YYYY-MM-DD dates');
  const rng = new Mulberry32(seed);
  const t: number[] = [];
  const o: number[] = [];
  const h: number[] = [];
  const l: number[] = [];
  const c: number[] = [];
  const v: number[] = [];
  let last = 16000;
  for (let i = 0; i < cal.days.length; i++) {
    const D = cal.days[i];
    if (D < from || D > to) continue;
    const mult = 0.6 + rng.next();
    const drift = (rng.next() - 0.5) * 0.04;
    const close = cal.close[i];
    const rthEnd = close < 1320 ? close : 1320;
    const base = cal.base[i];
    for (let m = 0; m < close; m++) {
      const uSkip = rng.next();
      const z = rng.normal();
      const uHigh = rng.next();
      const uLow = rng.next();
      const uVol = rng.next();
      const inRth = m >= 930 && m < rthEnd;
      if (!inRth && uSkip < 0.35) continue;
      const P = inRth ? profile(m) : 0.35;
      const sigma = P * mult;
      const move = sigma * z + (inRth ? drift : 0);
      const open = last;
      const cl = open + R(move / 0.25);
      const hi = Math.max(open, cl) + Math.floor(((uHigh * sigma) / 0.25) * 0.5);
      const lo = Math.min(open, cl) - Math.floor(((uLow * sigma) / 0.25) * 0.5);
      const vol = inRth ? Math.floor(200 + 1800 * uVol * P * mult) : Math.floor(20 + 180 * uVol);
      t.push(base + m * MS_MINUTE);
      o.push(open * 0.25);
      h.push(hi * 0.25);
      l.push(lo * 0.25);
      c.push(cl * 0.25);
      v.push(vol);
      last = cl;
    }
  }
  return {
    length: t.length,
    t: Float64Array.from(t),
    open: Float64Array.from(o),
    high: Float64Array.from(h),
    low: Float64Array.from(l),
    close: Float64Array.from(c),
    volume: Float64Array.from(v),
    label: `demo seed ${seed}`,
  };
}

/** The demo bars as CSV, with New York offsets (SPEC § 12.4). */
export function demoBarsCsv(options: DemoOptions = {}): string {
  const cal = options.calendar ?? defaultCalendar();
  const b = demoBars(options);
  const out: string[] = ['timestamp,open,high,low,close,volume'];
  for (let i = 0; i < b.length; i++)
    out.push(`${isoWithOffset(cal.ny, b.t[i])},${b.open[i]},${b.high[i]},${b.low[i]},${b.close[i]},${b.volume![i]}`);
  return out.join('\n') + '\n';
}
